    /// media together and perform any crash recovery on a separate writable copy.
    pub fn open(path: &Path) -> Result<Self> {
        Self::open_profile(path, 1)
    }
    fn open_profile(path: &Path, profile: i64) -> Result<Self> {
        Self::open_profile_configured(path, profile, |_| Ok(()))
    }
    // Inventory installs stricter limits and cancellation before the first SQL
    // read; ordinary recovery keeps its existing defaults.
    fn open_profile_configured(
        path: &Path,
        profile: i64,
        before_read: impl FnOnce(&Connection) -> Result<()>,
    ) -> Result<Self> {
        private_file(path)?;
        let source = std::fs::canonicalize(path)?;
        let ledger = Ledger {
            // surface-write: evidence-recovery-source:database-wal,evidence-recovery-source:database-shm
            conn: crate::persistence::open_sqlite_recovery_source(
                crate::persistence::SurfaceWrite::EvidenceRecoverySource,
                &source,
            )?,
        };
        ledger.conn.set_limit(
            rusqlite::limits::Limit::SQLITE_LIMIT_LENGTH,
            RECOVERY_SQLITE_LENGTH_LIMIT,
        )?;
        ledger.conn.busy_timeout(Duration::from_secs(5))?;
        before_read(&ledger.conn)?;
        ledger.conn.execute_batch("PRAGMA query_only=ON; BEGIN;")?;
        // Reading the profile pins the transaction before the handle escapes.
        ledger.check_profile(profile)?;
        Ok(Self { ledger, source })
    }

    /// Observed raw frontier in this pinned transaction, not a history certificate.
    pub fn snapshot(&self) -> Result<Snapshot> {
        let through: i64 = self.ledger.conn.query_row(
            "SELECT COALESCE(MAX(sequence),0) FROM commits NOT INDEXED",
            [],
            |r| r.get(0),
}

fn sqlite_paths(path: &Path) -> Vec<PathBuf> {
    let mut paths = vec![path.to_path_buf()];
    for suffix in ["-journal", "-wal", "-shm"] {
        let mut name = path.as_os_str().to_os_string();
        name.push(suffix);
        paths.push(PathBuf::from(name));
    }
    paths
}

fn same_existing_file(a: &Path, b: &Path) -> bool {
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        matches!((std::fs::metadata(a), std::fs::metadata(b)), (Ok(a), Ok(b)) if a.dev() == b.dev() && a.ino() == b.ino())
    }
    #[cfg(not(unix))]
    {
        matches!((std::fs::canonicalize(a), std::fs::canonicalize(b)), (Ok(a), Ok(b)) if a == b)
    }
}

// Conservative Unicode casing also rejects aliases such as long-s in `-ſhm`
// before a file exists. This is not an emulation of every filesystem's collation;
// existing-file identity below supplies the actual filesystem alias check.
// Qualified on case-insensitive APFS; other filesystem collations (including
// HFS+, NTFS/SMB and ext4 casefold) and arbitrary multi-codepoint aliases are
// not qualified. This helper does not fence concurrent hostile path replacement.
fn sqlite_name_eq(a: &std::ffi::OsStr, b: &std::ffi::OsStr) -> bool {
    match (a.to_str(), b.to_str()) {
        (Some(a), Some(b)) => a
            .chars()
            .flat_map(char::to_uppercase)
            .flat_map(char::to_lowercase)
            .eq(b
                .chars()
                .flat_map(char::to_uppercase)
                .flat_map(char::to_lowercase)),
        _ => a
            .as_encoded_bytes()
            .eq_ignore_ascii_case(b.as_encoded_bytes()),
    }
}

fn sqlite_destination(source: &Path, destination: &Path) -> Result<PathBuf> {
    let parent = std::fs::canonicalize(parent_directory(destination))?;
    let name = destination
        .file_name()
        .ok_or(Error::Invalid("destination filename"))?;
    let destination = parent.join(name);
    let target_paths = sqlite_paths(&destination);
    let source_paths = sqlite_paths(source);
    if target_paths.iter().any(|target| {
        source_paths.iter().any(|source| {
            sqlite_name_eq(target.as_os_str(), source.as_os_str())
                || same_existing_file(target, source)
        })
    }) {
        return Err(Error::Invalid("destination overlaps source SQLite files"));
    }
    // Resolve the existing base before a currently absent sidecar can be
    // created through an alternate basename (including Unicode and hard links).
    if let Some((base, suffix)) = name.to_str().and_then(|name| name.rsplit_once('-')) {
        if ["journal", "wal", "shm"].iter().any(|reserved| {
            sqlite_name_eq(std::ffi::OsStr::new(suffix), std::ffi::OsStr::new(reserved))
        }) && same_existing_file(&parent.join(base), source)
        {
            return Err(Error::Invalid("destination aliases source SQLite sidecar"));
        }
    }
    unused_sqlite_sidecars(&destination)?;
    Ok(destination)
}

fn unused_sqlite_sidecars(destination: &Path) -> Result<()> {
    // A new main filename alone is insufficient: SQLite owns these sibling names.
    for path in sqlite_paths(destination).iter().skip(1) {
        match std::fs::symlink_metadata(path) {
            Ok(_) => return Err(Error::Invalid("destination SQLite sidecar already exists")),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
            Err(e) => return Err(e.into()),
        }
    }
    Ok(())
}

pub fn ciphertext_cid(bytes: &[u8]) -> Cid {
    let mut raw = vec![1, 0x55, 0x12, 0x20];
    raw.extend(Sha256::digest(bytes));
    Cid::from_bytes(&raw).expect("fixed raw SHA256 CID")
}

